    "InternalHeader": {
      "name": "InternalHeader",
      "group": "component",
      "status": "current",
      "description": "Visible internal header with a user menu and logout action.",
      "docs": "https://aksel.nav.no/komponenter/core/i-header",
      "keywords": [
        "internal header",
        "header",
        "app chrome",
        "navigation",
        "top bar"
      ],
      "props": [],
      "snippet": {
        "jsx": "<InternalHeader>\n  <InternalHeader.Title as=\"h1\">Sykepenger</InternalHeader.Title>\n  <Spacer />\n  <ActionMenu>\n    <ActionMenu.Trigger>\n      <InternalHeader.UserButton name=\"Ola N.\" description=\"Enhet: Skien\" />\n    </ActionMenu.Trigger>\n    <Theme theme={resolvedTheme as \"light\" | \"dark\"}>\n      <ActionMenu.Content align=\"end\">\n        <ActionMenu.Label>\n          <dl style={{ margin: \"0\" }}>\n            <BodyShort as=\"dt\" size=\"small\">\n              Ola Normann\n            </BodyShort>\n            <Detail as=\"dd\">D123456</Detail>\n          </dl>\n        </ActionMenu.Label>\n        <ActionMenu.Divider />\n        <ActionMenu.Group aria-label=\"Handlinger\">\n          <ActionMenu.Item>\n            Logg ut <Spacer /> <LeaveIcon aria-hidden fontSize=\"1.5rem\" />\n          </ActionMenu.Item>\n        </ActionMenu.Group>\n      </ActionMenu.Content>\n    </Theme>\n  </ActionMenu>\n</InternalHeader>",
        "hooks": "const useResolvedTheme = () => {\n  const readResolvedTheme = () =>\n    document.documentElement.classList.contains(\"dark\") ? \"dark\" : \"light\"\n  const [resolvedTheme, setResolvedTheme] = useState<\"light\" | \"dark\">(() => readResolvedTheme())\n\n  useEffect(() => {\n    const observer = new MutationObserver(() => {\n      setResolvedTheme(readResolvedTheme())\n    })\n\n    observer.observe(document.documentElement, {\n      attributes: true,\n      attributeFilter: [\"class\"],\n    })\n\n    return () => observer.disconnect()\n  }, [])\n\n  return resolvedTheme\n}\nconst resolvedTheme = useResolvedTheme()"
      }
    },
